import re

def replace_table(text, header_regex, new_table):
    m=re.search(header_regex, text, flags=re.M)
    if not m:
        raise SystemExit(f'Could not find table header via {header_regex!r}')
    start=m.start()
    # find end: next blank line after table
    after=text[start:]
    # table ends at first occurrence of two newlines after a table row block
    # We'll end at the first line that does not start with '|' after starting.
    lines=after.splitlines(True)
    end_idx=0
    in_table=False
    for i,ln in enumerate(lines):
        if i==0:
            in_table=True
            continue
        if in_table:
            if not ln.lstrip().startswith('|') and ln.strip()!='':
                end_idx=sum(len(l) for l in lines[:i])
                break
    if end_idx==0:
        end_idx=sum(len(l) for l in lines)
    return text[:start] + new_table + "\n\n" + after[end_idx:]

